BEGIN;
CREATE TABLE auth_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK(email=lower(email)), password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), disabled_at timestamptz);
CREATE TABLE auth_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE INDEX auth_sessions_user_id_idx ON auth_sessions(user_id);
CREATE INDEX auth_sessions_expires_at_idx ON auth_sessions(expires_at);
CREATE TABLE auth_api_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 80), token_hash text NOT NULL UNIQUE, scopes text[] NOT NULL CHECK(cardinality(scopes)>0), created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, expires_at timestamptz, revoked_at timestamptz);
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name))>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members (organization_id uuid REFERENCES organizations(id), user_id uuid REFERENCES auth_users(id), role text NOT NULL CHECK(role IN ('owner','admin','analyst','viewer')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, UNIQUE(organization_id,id));
CREATE TABLE subscription_plans (code text PRIMARY KEY, monthly_cents integer NOT NULL CHECK(monthly_cents>=0), enabled boolean NOT NULL DEFAULT false);
CREATE TABLE subscriptions (organization_id uuid PRIMARY KEY REFERENCES organizations(id), plan_code text NOT NULL REFERENCES subscription_plans(code), status text NOT NULL CHECK(status IN ('inactive','trial','active','past_due','canceled')), provider_subscription_id text UNIQUE);
CREATE TABLE security_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), actor_id uuid REFERENCES auth_users(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE organization_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY;
ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE security_audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
ALTER TABLE organization_members FORCE ROW LEVEL SECURITY;
ALTER TABLE workspaces FORCE ROW LEVEL SECURITY;
ALTER TABLE subscriptions FORCE ROW LEVEL SECURITY;
ALTER TABLE security_audit FORCE ROW LEVEL SECURITY;
COMMIT;
